/**
 * Response contracts: what the server must send. The port checks every answer against these and
 * the harness shows any mismatch. Regenerate after a backend change (widgets:contract).
 */
import { s, type Infer } from '../../core/shape';

// <contract users.organization.list>
/** GET /api/orgs/me/users → List<Dtos.OrgUserRow> (OrgController#meUsers, org.user:read). Generated by widgets:contract. */
export const USERS_ORGANIZATION_LIST = s.array(s.object('OrgUserRow', {
  id: s.nullable(s.string()),
  name: s.nullable(s.string()),
  username: s.nullable(s.string()),
  role: s.nullable(s.string()),
  orgRole: s.nullable(s.string()),
  status: s.nullable(s.string()),
  phone: s.nullable(s.string()),
  email: s.nullable(s.string()),
}));
export type UsersOrganizationList = Infer<typeof USERS_ORGANIZATION_LIST>;
// </contract users.organization.list>

// <contract users.organization.create>
/** POST /api/orgs/me/users → Dtos.OrgStaffView (OrgController#addStaff, org.user:create). Generated by widgets:contract. */
export const USERS_ORGANIZATION_CREATE = s.object('OrgStaffView', {
  id: s.nullable(s.string()),
  name: s.nullable(s.string()),
  username: s.nullable(s.string()),
  phone: s.nullable(s.string()),
  email: s.nullable(s.string()),
  role: s.nullable(s.string()),
  orgRole: s.nullable(s.string()),
  status: s.nullable(s.string()),
  activatedAt: s.nullable(s.dateTime()),
});
export type UsersOrganizationCreate = Infer<typeof USERS_ORGANIZATION_CREATE>;
// </contract users.organization.create>

// <contract users.organization.setup-link>
/** POST /api/orgs/users/{id}/resend-activation → ResponseEntity<?> (ActivationController#resend, org.user:administer). Generated by widgets:contract. */
export const USERS_ORGANIZATION_SETUP_LINK = s.any();
export type UsersOrganizationSetupLink = Infer<typeof USERS_ORGANIZATION_SETUP_LINK>;
// </contract users.organization.setup-link>

// <contract users.organization.deactivate>
/** POST /api/orgs/users/{id}/deactivate → Dtos.Message (OrgController#deactivate, org.user:delete). Generated by widgets:contract. */
export const USERS_ORGANIZATION_DEACTIVATE = s.object('Message', {
  message: s.nullable(s.string()),
  label: s.nullable(s.string()),
});
export type UsersOrganizationDeactivate = Infer<typeof USERS_ORGANIZATION_DEACTIVATE>;
// </contract users.organization.deactivate>

// <request users.organization.create>
/** POST /api/orgs/me/users sends Dtos.StaffRequest (OrgController#addStaff, org.user:create). Generated by widgets:contract. */
export const USERS_ORGANIZATION_CREATE_REQUEST = s.object('StaffRequest', {
  name: s.string(),
  phone: s.string(),
  username: s.nullable(s.string()),
  email: s.string(),
  orgRole: s.nullable(s.enum('ADMIN', 'STAFF')),
  password: s.nullable(s.string()),
});
export type UsersOrganizationCreateRequest = Infer<typeof USERS_ORGANIZATION_CREATE_REQUEST>;
// </request users.organization.create>

/**
 * Hand-written contract for the setup-link response. The controller deliberately returns
 * ResponseEntity<?> so it can serve two server modes: gateway mode returns IdpSetupLinkService.Result,
 * while legacy mode returns Dtos.Message with the link in `label`.
 */
export const USERS_ORGANIZATION_SETUP_LINK_RESPONSE = s.oneOf(
  s.object('SetupLinkResult', {
    setupLink: s.string(),
    expiresAt: s.dateTime(),
    delivered: s.boolean(),
    deliveryMessage: s.string(),
  }),
  s.object('Message', {
    message: s.string(),
    label: s.nullable(s.string()),
  }),
);
export type UsersOrganizationSetupLinkResponse = Infer<typeof USERS_ORGANIZATION_SETUP_LINK_RESPONSE>;

/** Commands without a request body still have an explicit, checkable body contract. */
export const USERS_ORGANIZATION_SETUP_LINK_REQUEST = s.object('NoBody', {});
export const USERS_ORGANIZATION_DEACTIVATE_REQUEST = s.object('NoBody', {});
